const gs = q => 'https://www.google.com/search?q=' + encodeURIComponent(q);
const BOOKS = [
  { g: ['lim', 'der', 'app', 'int'], t: ['Ларри Гоник. «Матан. Краткий курс в комиксах» (КоЛибри, 2017)', 'Ларри Гоник. «Матан. Комикстегі қысқаша курс» (КоЛибри, 2017)', 'Larry Gonick. "The Cartoon Guide to Calculus"'], q: 'Гоник Матан. Краткий курс в комиксах',
    d: ['Весь школьный анализ в картинках и с юмором. Гл. 1 «Пределы» (с. 59), гл. 2 «Производная» (с. 83), гл. 3 «Цепи, цепи, цепи» — сложная функция (с. 107), гл. 5 «Оптимизация» (с. 131), гл. 6 «Действуем локально» — приближённые вычисления (с. 151), гл. 9–11 — первообразная, определённый интеграл, основная теорема (с. 175–193), гл. 13 «Применение интегралов» (с. 211).', 'Бүкіл мектеп анализі суретпен, әзілмен. 1-тарау «Шектер» (59-б.), 2-тарау «Туынды» (83-б.), 3-тарау — күрделі функция (107-б.), 5-тарау «Оңтайландыру» (131-б.), 6-тарау — жуықтап есептеу (151-б.), 9–11-тараулар — алғашқы функция, анықталған интеграл, негізгі теорема (175–193-б.), 13-тарау «Интегралдарды қолдану» (211-б.).', 'All of school calculus in pictures and jokes. Ch. 1 Limits, ch. 2 The Derivative, ch. 3 Chain rule, ch. 5 Optimisation, ch. 6 Acting locally (approximation), ch. 9–11 antiderivatives, the definite integral, the fundamental theorem, ch. 13 Using integrals. (Page numbers in the Russian edition: 59, 83, 107, 131, 151, 175–193, 211.)'] },
  { g: ['lim', 'der', 'app', 'int'], t: ['Бен Орлин. «Время переменных. Математический анализ в безумном мире» (Альпина нон-фикшн, 2021)', 'Бен Орлин. «Айнымалылар уақыты. Ақылға сыймайтын әлемдегі математикалық анализ» (Альпина нон-фикшн, 2021)', 'Ben Orlin. "Change Is the Only Constant: The Wisdom of Calculus in a Madcap World"'], q: 'Орлин Время переменных Математический анализ в безумном мире',
    d: ['28 рассказов без формул, но с идеями. К производной: II «Вечно падающая Луна» (с. 31), V «Когда Миссисипи текла на миллион миль» — опасность линейного прогноза (с. 67), VI «Шерлок Холмс и неправильный велосипед» (с. 79). К применению производной: XI «Принцесса с городской окраины» — задача Дидоны (с. 135), XIV «Это твой пёс-профессор» (с. 171). К интегралу: XVIII «Линия городского горизонта Римана» (с. 217), XXII «1994-й, год, когда родился математический анализ» (с. 263), XXVII «Трубы, Гавриил, трубы!» (с. 319).', 'Формуласыз, бірақ идеяға толы 28 әңгіме. Туындыға: II (31-б.), V — сызықтық болжамның қаупі (67-б.), VI «Шерлок Холмс және дұрыс емес велосипед» (79-б.). Туындыны қолдануға: XI — Дидона есебі (135-б.), XIV — профессор ит (171-б.). Интегралға: XVIII «Риманның қала көкжиегі» (217-б.), XXII «1994 жыл» (263-б.), XXVII «Гавриил кернейі» (319-б.).', '28 stories with ideas instead of formulas. For derivatives: II The Ever-Falling Moon, V When the Mississippi Ran a Million Miles, VI Sherlock Holmes and the Bicycle of Misdirection. For applications: XI The Princess on the Edge of Town (Dido), XIV That\'s Professor Dog to You. For integrals: XVIII Riemann City Skyline, XXII 1994, the Year Calculus Was Born, XXVII Gabriel, Blow Your Trumpet.'] },
  { g: ['der', 'int'], t: ['Хироюки Кодзима, Син Тогами. «Занимательная математика. Производные и интегралы. Манга» (ДМК Пресс, 2015)', 'Хироюки Кодзима, Син Тогами. «Қызықты математика. Туындылар мен интегралдар. Манга» (ДМК Пресс, 2015)', 'Hiroyuki Kojima, Shin Togami. "The Manga Guide to Calculus"'], q: 'Кодзима Тогами Занимательная математика Производные и интегралы манга',
    d: ['Начинающий репортёр Норико учится у редактора Сэки объяснять новости с помощью производной: главная мысль книги — любую функцию вблизи точки можно заменить линейной. Примеры из экономики (спрос и предложение), экологии и статистики. Хорошо читать вместе с темами «Дифференциал» и «Приближённые вычисления».', 'Жас тілші Норико редактор Сэкиден жаңалықтарды туынды арқылы түсіндіруді үйренеді: кітаптың басты ойы — кез келген функцияны нүкте маңында сызықтық функциямен алмастыруға болады. Экономика, экология, статистикадан мысалдар. «Дифференциал» және «Жуықтап есептеу» тақырыптарымен бірге оқыған жақсы.', 'Rookie reporter Noriko learns from her editor Seki to explain the news with derivatives. The key idea: near a point any function can be replaced by a linear one. Examples from economics, ecology and statistics. Goes well with "Differential" and "Approximate calculations".'] },
  { g: ['de'], t: ['Сато Минору. «Занимательная математика. Дифференциальные уравнения. Манга» (ДМК Пресс, 2018)', 'Сато Минору. «Қызықты математика. Дифференциалдық теңдеулер. Манга» (ДМК Пресс, 2018)', 'Minoru Sato. "The Manga Guide to Differential Equations" (Japanese/Russian editions)'], q: 'Сато Минору Занимательная математика Дифференциальные уравнения манга',
    d: ['Школьница Мидзуки, студент Нояма и богиня чисел разбирают, почему остывает кофе, как растёт численность оленей на Хоккайдо, как разгоняется ракета и почему мосты рассчитывают на колебания. Подходит ко всему разделу «Дифференциальные уравнения».', 'Оқушы Мидзуки, студент Нояма және сандар тәңірі кофенің неге салқындайтынын, Хоккайдодағы бұғылар санының қалай өсетінін, зымыранның қалай үдейтінін және көпірлердің тербеліске неге есептелетінін талдайды. «Дифференциалдық теңдеулер» бөліміне түгел сәйкес келеді.', 'Schoolgirl Mizuki, student Noyama and the goddess of numbers explore why coffee cools, how the Hokkaido deer population grows, how a rocket accelerates and why bridges are designed for oscillations. Fits the whole "Differential equations" unit.'] },
  { g: ['lim', 'der', 'int', 'de'], t: ['Г. Н. Берман. «Сборник задач по курсу математического анализа»', 'Г. Н. Берман. «Математикалық анализ курсы бойынша есептер жинағы»', 'G. N. Berman. "A Problem Book in Mathematical Analysis"'], q: 'Берман Сборник задач по курсу математического анализа',
    d: ['Классический задачник: тысячи задач от простых до олимпийских, много прикладных — на скорость, работу, давление. Тем, кому мало задач курса.', 'Классикалық есептер жинағы: қарапайымнан күрделіге дейін мыңдаған есеп, қолданбалылары көп — жылдамдық, жұмыс, қысым. Курс есептері аз болғандарға.', 'A classic problem book: thousands of problems from easy to hard, many applied ones — speed, work, pressure. For those who want more.'] },
  { g: ['lim', 'der', 'int'], t: ['Н. С. Знаенко. «Опорные схемы по высшей математике» (Ульяновск, 2011)', 'Н. С. Знаенко. «Жоғары математика бойынша тірек сызбалар» (Ульяновск, 2011)', 'N. S. Znaenko. "Reference charts for higher mathematics" (in Russian)'], q: 'Знаенко Опорные схемы по высшей математике',
    d: ['Вся теория в виде схем и таблиц: удобно повторять перед контрольной. Таблицы производных и интегралов из этого пособия — в нашем справочнике и тренажёре формул.', 'Бүкіл теория сызба мен кесте түрінде: бақылау алдында қайталауға ыңғайлы. Осы құралдағы туындылар мен интегралдар кестесі — біздің анықтамалық пен формула жаттықтырғышында.', 'All the theory as charts and tables: handy for revision. Its tables of derivatives and integrals are in our handbook and formula drill.'] }
];
