/* ---------- настройки учителя и генератор рабочих листов ---------- */
let WS = { seed: 1 };
function wsBuild() {
  const topics = [...document.querySelectorAll('.ws-topic:checked')].map(x => x.value), lv = [1, 2, 3].filter(l => $('ws-l' + l).checked);
  if (!topics.length) { toast(t('wsNone')); return; }
  const n = Math.max(1, Math.min(30, +$('ws-n').value || 8)), V = Math.max(1, Math.min(8, +$('ws-v').value || 2)), applied = $('ws-applied').checked, sol = $('ws-sol').checked, space = $('ws-space').checked, title = $('ws-title').value.trim() || t('wsDef');
  const pools = topics.map(id => { const tp = topicById(id); let ids = applied ? PRACT.filter(x => x.split('~')[0] === id) : Array.from({ length: GEN[id].length }, (_, i) => id + '~' + i); return ids.filter(x => !lv.length || lv.includes(getTask(x, 700).lvl)); }).filter(p => p.length);
  if (!pools.length) { toast(t('genNear')); return; }
  const slots = []; for (let round = 0; slots.length < n && round < 200; round++) for (const p of pools) if (slots.length < n) slots.push([p[round % p.length], Math.floor(round / p.length)]);
  const letters = LANG === 'en' ? 'ABCDEF' : 'АБВГДЕ', sheets = [], keys = [];
  for (let v = 1; v <= V; v++) {
    const tasks = slots.map(([id, rep], i) => getTask(id, 1000 + WS.seed * 131 + v * 17 + rep * 7));
    sheets.push(`<section class="ws-sheet"><header><h2>${esc(title)}</h2><b>${t('wsVar')} ${v}</b></header><div class="ws-meta"><span>${t('wsName')}: ____________________________</span><span>${t('wsClass')}: ________</span><span>${t('wsDate')}: ____________</span></div>
     <ol class="ws-tasks">${tasks.map(tk => `<li><div class="ws-q">${mx(tk.q)}</div>${tk.opts ? `<div class="ws-opts">${tk.opts.map((o, i) => `<span><b>${letters[i]})</b> ${mx(o)}</span>`).join('')}</div>` : ''}${tk.fields ? `<div class="ws-opts">${tk.fields.map(f => `<span>${mx(f.label)} = ______</span>`).join('')}</div>` : ''}${space ? '<div class="ws-space"></div>' : ''}</li>`).join('')}</ol></section>`);
    keys.push(`<div class="ws-key"><h3>${t('wsVar')} ${v}</h3><ol>${tasks.map(tk => `<li>${tk.opts && !Array.isArray(tk.a) ? `<b>${letters[tk.a]})</b> ` : tk.opts ? `<b>${tk.a.map(i => letters[i]).join(', ')})</b> ` : ''}${mx(tk.ans)}${tk.unit ? ' ' + mx(tk.unit) : ''}${sol ? `<ol class="ws-steps">${tk.steps.map(s => `<li>${mx(s)}</li>`).join('')}</ol>` : ''}</li>`).join('')}</ol></div>`);
  }
  $('ws-out').innerHTML = `<div class="bar no-print"><button class="btn primary" onclick="window.print()">${t('print')}</button><button class="btn" onclick="WS.seed++;wsBuild()">${ico('refresh')} ${t('wsOther')}</button></div>${sheets.join('')}<section class="ws-sheet"><header><h2>${esc(title)}</h2><b>${t('wsKey')}</b></header>${keys.join('')}</section>`;
  $('ws-out').closest('.page').classList.add('ws-page');
  $('ws-out').scrollIntoView({ behavior: 'smooth' });
}
function wsAll(g, on) { document.querySelectorAll(`.ws-topic[data-g="${g}"]`).forEach(x => { x.checked = on; }); }
function renderSettings() {
  $('main').innerHTML = `<div class="page"><h1 class="ws-hide">${ico('gear')} ${t('settings')}</h1>
  <div class="card ws-hide"><h2 style="margin-top:0">${t('wsT')}</h2><p class="muted">${t('wsLead')}</p>
   <div class="ws-topics">${GROUPS.map(g => `<fieldset data-g="${g.id}"><legend><label class="row"><input type="checkbox" onchange="wsAll('${g.id}',this.checked)"><b style="color:var(--g)">${esc(groupName(g.id))}</b> <span class="muted small">(${t('wsAllT')})</span></label></legend>${TOPICS.filter(x => x.g === g.id).map(x => `<label class="row"><input type="checkbox" class="ws-topic" data-g="${g.id}" value="${x.id}"><span>${x.n}. ${esc(C(x.id).t)}</span></label>`).join('')}</fieldset>`).join('')}</div>
   <div class="grid3" style="margin-top:14px"><label><b>${t('wsTitle')}</b><input id="ws-title" value="${t('wsDef')}"></label><label><b>${t('wsN')}</b><input id="ws-n" type="number" min="1" max="30" value="8"></label><label><b>${t('wsV')}</b><input id="ws-v" type="number" min="1" max="8" value="2"></label></div>
   <div class="row wrap" style="margin-top:14px"><b>${t('wsLvl')}:</b>${[1, 2, 3].map(l => `<label class="row"><input type="checkbox" id="ws-l${l}" ${l < 3 ? 'checked' : ''}><span>${t('lvl' + l)}</span></label>`).join('')}</div>
   <div class="row wrap" style="margin-top:10px"><label class="row"><input type="checkbox" id="ws-space" checked><span>${t('wsSpace')}</span></label><label class="row"><input type="checkbox" id="ws-applied"><span>${t('wsApplied')}</span></label><label class="row"><input type="checkbox" id="ws-sol"><span>${t('wsSol')}</span></label></div>
   <div class="row" style="margin-top:16px"><button class="btn primary" onclick="wsBuild()">${ico('table')} ${t('wsMake')}</button></div></div>
  <div id="ws-out"></div>
  <div class="card stack ws-hide" style="margin-top:18px"><h2 style="margin:0">${t('settingsStudy')}</h2><label class="row"><input type="checkbox" ${S.settings.showSol ? 'checked' : ''} onchange="S.settings.showSol=this.checked;save()"><span>${t('showSol')}</span></label>
   <label class="row"><span>${t('gate')}</span><select style="width:90px" onchange="S.settings.gate=+this.value;save()">${[1, 2, 3, 4, 5].map(n => `<option ${n === S.settings.gate ? 'selected' : ''}>${n}</option>`).join('')}</select></label>
   <div class="row wrap"><a class="btn" href="#progress">${ico('chart')} ${t('progress')}</a><a class="btn" href="#exam">${ico('check')} ${t('exam')}</a><button class="btn" onclick="exportCsv()">${t('exportCsv')}</button></div></div>${footer()}</div>`;
}
ROUTES.settings = renderSettings;

/* ---------- генератор задач трёх уровней в ИИ-наставнике ---------- */
let GENLVL = 1;
function genFind(id, lvl) {
  const n = GEN[id].length, found = [];
  for (let d = 0; d < 3 && !found.length; d++) for (let s = 0; s < n; s++) for (const v of [300, 301, 302]) { const tk = getTask(id + '~' + s, v); if (Math.abs(tk.lvl - lvl) === d) { found.push([s, d]); break; } }
  const [s, d] = found[drRnd(found.length)];
  return { id: id + '~' + s, variant: 300 + drRnd(5000), near: d > 0 };
}
function genLocal() {
  const id = $('gen-topic').value, f = genFind(id, GENLVL);
  $('gen-out').innerHTML = (f.near ? `<p class="muted small">${t('genNear')}</p>` : '') + taskCard(f.id, 'random', 1, f.variant);
}
function genAi() {
  const c = C($('gen-topic').value), lv = ['', 'базовый: одно действие по формуле', 'средний: 2–3 шага, нужно выбрать метод', 'продвинутый: несколько идей или прикладной сюжет'][GENLVL];
  aiSend(`Придумай одну новую задачу по теме «${c.t}» (${c.s}) для 10–11 класса. Уровень сложности ${GENLVL} из 3 (${lv}). Числа подбери так, чтобы ответ был «красивым». Напиши только условие, без решения и ответа. Потом дождись моего ответа, проверь его и, если я ошибусь, дай подсказку, а полное решение по шагам покажи только когда я попрошу.`, `${t('genT')}: ${c.t} · ${t('lvl' + GENLVL)}`);
}
function genLvl(l) { GENLVL = l; document.querySelectorAll('#gen-lvl button').forEach((b, i) => b.classList.toggle('active', i + 1 === l)); }
const _renderAI = renderAI;
renderAI = function (keep) {
  _renderAI(keep);
  const html = `<div class="card" id="gen-card" style="margin-bottom:16px"><h2 style="margin-top:0">${ico('cards')} ${t('genT')}</h2><p class="muted" style="margin-top:0">${t('genLead')}</p>
   <div class="row wrap"><select id="gen-topic" style="max-width:380px">${GROUPS.map(g => `<optgroup label="${esc(groupName(g.id))}">${TOPICS.filter(x => x.g === g.id).map(x => `<option value="${x.id}">${x.n}. ${esc(C(x.id).t)}</option>`).join('')}</optgroup>`).join('')}</select>
   <div class="seg" id="gen-lvl" style="margin:0">${[1, 2, 3].map(l => `<button class="${l === GENLVL ? 'active' : ''}" onclick="genLvl(${l})">${t('lvl' + l)}</button>`).join('')}</div>
   <button class="btn primary" onclick="genLocal()">${ico('refresh')} ${t('genGo')}</button><button class="btn" onclick="genAi()">${ico('bot')} ${t('genAi')}</button></div><div id="gen-out" style="margin-top:14px"></div></div>`;
  const setup = $('ai-setup'); if (setup) setup.insertAdjacentHTML('afterend', html);
};

/* ---------- слайды: разминка, комикс, история, подробный пример, запоминалка, лист самооценки ---------- */
const BLITZ_LIM = [[R`\lim_{x\to\infty}\dfrac1x`, '0'], [R`\lim_{x\to3}x^2`, '9'], [R`\lim_{x\to0}\dfrac{\sin x}{x}`, '1'], [R`\lim_{x\to\infty}\dfrac{2x+1}{x}`, '2'], [R`\lim_{n\to\infty}\left(1+\dfrac1n\right)^n`, 'e'], [R`\lim_{x\to2}\dfrac{x^2-4}{x-2}`, '4']];
const _buildSlides = buildSlides;
buildSlides = function (tp) {
  const out = _buildSlides(tp), c = C(tp.id), last = out.pop();
  const T = tp.g === 'lim' ? BLITZ_LIM : (tp.g === 'int' || tp.g === 'de' ? INT_T : DER_T), k0 = tp.n * 3, six = tp.g === 'lim' ? T : Array.from({ length: 6 }, (_, i) => T[(k0 + i * 7) % T.length]);
  const warm = `<span class="sl-kicker">${t('slWarm')}</span><p class="muted">${t('slWarmTip')}</p><div class="sl-formulas warm">${six.map(p => `<div class="f">${tex(fx(p[0] + R`=\ ?`), true)}</div>`).join('')}</div><details class="solution"><summary>${ico('bulb')} ${t('slAnswers')}</summary><div class="sl-formulas warm" style="padding:14px">${six.map(p => `<div class="f">${tex(fx(p[0] + '=' + p[1]), true)}</div>`).join('')}</div></details>`;
  const head = [warm]; if (COMIX[tp.id] && COMIX[tp.id].img) head.push(comicBlock(tp.id));
  head.push(`<div class="sl-pic"><div><span class="sl-kicker">${t('histT')}</span><div class="sl-hist">${mx(tr(histOf(tp)))}</div></div><img src="${groupPic(tp.g)}" alt=""></div>`);
  out.splice(2, 0, ...head);
  if (typeof DETAIL !== 'undefined' && DETAIL[tp.id]) out.push(`<span class="sl-kicker">${t('detailT')}</span>${detailHtml(tp.id, true)}`);
  if (MNEMO[tp.id]) out.push(`<div class="sl-pic"><div><span class="sl-kicker">${t('mnemoT')}</span><p class="sl-big">${mx(tr(MNEMO[tp.id]))}</p></div><img src="assets/img/fact.jpg" alt=""></div>`);
  out.push(`<span class="sl-kicker">${t('slSelf')}</span><div class="table-scroll"><table class="ref self"><tr><th>${t('selfSkill')}…</th><th>${t('selfA')}</th><th>${t('selfB')}</th><th>${t('selfC')}</th></tr>${c.o.map(x => `<tr><td>${mx(x)}</td><td>☐</td><td>☐</td><td>☐</td></tr>`).join('')}</table></div>`);
  out.push(last);
  return out;
};
